entries[420211] = { ["name"] = "Meisterschaft: Entzünden", ["text"] = "Euer Ziel erleidet im Verlauf von 9 Sek. zusätzlichen Feuerschaden in Höhe von 5.0% des gesamten direkten Schadens, den Ihr mit Euren Zaubern 'Feuerball', 'Feuerschlag', 'Versengen', 'Pyroschlag' und 'Flammenstoß' verursacht. Wenn dieser Effekt erneut ausgelöst wird, bevor seine Dauer abläuft, wird der verbleibende Schaden dem neuen Effekt von 'Entzünden' hinzugefügt.\n\n'Feuerschlag' bewirkt, dass Euer Effekt 'Entzünden' sich auf 3 Gegner in der Nähe ausbreitet." }
