entries[420435] = { ["name"] = "Traumsprunganleitung", ["text"] = "Sofort\nSteuert Eure Traumsprungvereinigung zu Folgendem bei:\nTraumsprunglehren :\nErhaltene Erfahrung um 30% erhöht. Erhaltener Ruf auf den Dracheninseln um 0% erhöht. Traumwächter ausgeschlossen." }
entries[420436] = { ["name"] = "Traumsprunganleitung", ["text"] = "Sofort\nSteuert Eure Traumsprungvereinigung zu Folgendem bei:\nTraumsprunggrünwandler :\nIhr taucht teilweise in den Smaragdgrünen Traum ein, wodurch Ihr außerhalb des Kampfes schwerer zu entdecken seid und Eure nächsten Angriffe ermächtigt werden." }
entries[420437] = { ["name"] = "Traumsprunganleitung", ["text"] = "Sofort\nSteuert Eure Traumsprungvereinigung zu Folgendem bei:\nTraumsprungeinzelgänger :\nVerursachter Schaden, hervorgerufene Heilung und Bewegungsgeschwindigkeit um 25% erhöht und erlittener Schaden um 25% verringert, sofern Ihr Euch nicht innerhalb von 30 Metern um einen anderen Spielercharakter befindet." }
entries[420438] = { ["name"] = "Traumsprunganleitung", ["text"] = "Sofort\nSteuert Eure Traumsprungvereinigung zu Folgendem bei:\nTraumsprungrudeljäger :\nVerursachter Schaden, hervorgerufene Heilung und Bewegungsgeschwindigkeit für jeden Spielercharakter im Umkreis von 5 Metern um 5% erhöht." }
entries[420439] = { ["name"] = "Traumsprunganleitung", ["text"] = "Sofort\nSteuert Eure Traumsprungvereinigung zu Folgendem bei:\nTraumsprungverteidiger :\nRuft in regelmäßigen Abständen einen Traumsprungverteidiger heran, der einen Angriff auf Euch absorbiert und dann wieder in den Traum zurückkehrt." }
