entries[420644] = { ["name"] = "Traumreißen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFyrakk greift die Struktur des Smaragdgrünen Traums an, fügt allen Spielercharakteren 326356 Feuerschaden zu und öffnet einen Riss in die Feuerlande.\n\nSengende Hitze strömt durch den Riss, fügt allen Spielercharakteren 8 Sek. lang alle 1 Sek. 1450473 Feuerschaden zu und zieht sie zum Riss. Spielercharaktere, die weiter vom Riss entfernt sind, erleiden weniger Schaden.\n\nAuf Spielercharaktere, die in den Riss gezogen werden, werden ' Verbrannt '." }
