entries[420694] = { ["name"] = "Kerzenbrand", ["text"] = "100 Meter Reichweite\nWirken in 1 sek. 8 sek. Abklingzeit\nDer Kerzenkönig markiert zufällige Spielercharaktere. Kurz darauf schleudert er Kerzenflammen auf sie und fügt Zielen innerhalb von 5 Metern 8485573 Feuerschaden zu. Diese Flammen sind stark genug, um Werke aus Wachs zu schmelzen." }
entries[420695] = { ["name"] = "Spitzhacke wuchten", ["text"] = "100 Meter Reichweite\nSofort 8 sek. Abklingzeit\nDer Kerzenkönig bereitet eine übergroße Spitzhacke vor, um sie auf ein Ziel zu wuchten. Die Spitzhacke prallt auf das erste von ihr getroffene Ziel, fügt ihm 29 körperlichen Schaden zu und stößt es zurück. Erwischt sie stattdessen eine Wachsstatue, wird diese dadurch zerschmettert." }
entries[420696] = { ["name"] = "Dunkelflamme werfen", ["text"] = "100 Meter Reichweite\nSofort 8 sek. Abklingzeit\nDer Kerzenkönig markiert zufällige Spielercharaktere. Kurz darauf schleudert er die schattenhaften Flammen auf sie, fügt Zielen innerhalb von 5 Metern 2424449 Schattenschaden zu und absorbiert bei ihnen die nächsten 1660411 Heilung. Diese Flammen sind stark genug, um Werke aus Wachs zu schmelzen." }
