entries[420724] = { ["name"] = "Feuer dem Schatten zu Hilfe, Schatten dem Feuer zu Hilfe", ["text"] = "Sofort\nWenn Ihr Schattenschaden verursacht, verursacht Ihr nun zusätzlich 20% des Schadens als Feuerschaden und erhaltet einen Stapel von 'Berührung der Flamme'.\nWenn Ihr Feuerschaden verursacht, verursacht Ihr nun zusätzlich 20% des Schadens als Schattenschaden und erhaltet einen Stapel von 'Berührung der Dunkelheit'." }
entries[420726] = { ["name"] = "Unendliche Folter", ["text"] = "Sofort 3 min Abklingzeit\nVerbraucht alle Stapel von 'Berührung der Dunkelheit' und 'Berührung der Flamme', wodurch Ihr pro Stapel von 'Berührung der Dunkelheit' s1 Schattenflammenschaden und pro Stapel von 'Berührung der Flamme' s2 Schattenflammenschaden verursacht. Erlangt für 30 Sek. 'Pyretikumfinsternis', was Euren verursachten Feuerschaden um 1% pro Stapel von 'Berührung der Flamme' und Euren verursachten Schattenschaden um 1% pro Stapel von 'Berührung der Dunkelheit' erhöht." }
