entries[420731] = { ["name"] = "Zehrende Flammen", ["text"] = "Sofort 3 min Abklingzeit\nEure Zauber kosten zusätzlich 2% Gesundheit und verursachen 10% mehr Feuerschaden." }
entries[420732] = { ["name"] = "Lohe", ["text"] = "Sofort 3 min Abklingzeit\nWenn Ihr mit Euren Zaubern einem Gegner Schaden zufügt und diesem innerhalb von 5 Metern 3 Verbündete zur Seite stehen, erschafft Ihr einen Flammenbereich, in dem Gegner im Verlauf von 8 Sek. 0 Schaden erleiden. Es können maximal 10 solcher Flammenbereiche aktiv sein." }
