entries[420734] = { ["name"] = "Unauslöschlicher Scheiterhaufen", ["text"] = "Sofort 3 min Abklingzeit\nWandelt dauerhaft 20% Eurer maximalen Gesundheit in einen Flammenschild um, welcher Schaden in Höhe von 35% Eurer maximalen Gesundheit absorbiert. Wenn der Flammenschild aufgezehrt wurde oder entfernt wird, wird der dafür verantwortliche Gegner für 3 Sek. betäubt und der Flammenschild nach 8 Sek. wiederhergestellt." }
entries[420737] = { ["name"] = "Feuerfeen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nBedeckt ein Ziel mit Feuerfeen und erhöht für 14 Sek. dessen Verwundbarkeit gegenüber Feuerschaden. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit noch Unsichtbarkeit anwenden." }
