entries[420739] = { ["name"] = "Instabile Ladung", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nKyrioss durchdringt einen zufälligen Spielercharakter mit Elektrizität. Nach Entfernung entfesselt das Ziel eine Eruption elektrischer Energie, die allen Spielercharakteren 4849650 Naturschaden zufügt. Die Eruption kann sicher im zentralen Sturm entladen werden." }
